35	// getFullTerminalWidth returns the terminal width without the 80-char cap
36	// used by other commands. Activity benefits from wide output for bar charts.
37	func getFullTerminalWidth(w io.Writer) int {
38		if f, ok := w.(*os.File); ok {
39			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
40				return width
41			}
42		}
43		for _, f := range []*os.File{os.Stdout, os.Stderr} {
44			if f == nil {
45				continue
46			}
47			if width, _, err := term.GetSize(int(f.Fd())); err == nil && width > 0 { //nolint:gosec // G115: uintptr->int is safe for fd
48				return width
49			}
50		}
51		return 80
52	}
