328	func renderBrailleChart(w io.Writer, sty activityStyles, hourly []hourlyPoint, repos []repoContribution) {
329		// Agent breakdown header + total
330		agentTotals := make(map[string]int)
331		total := 0
332		for _, r := range repos {
333			total += r.Total
334			for agent, count := range r.Agents {
335				agentTotals[agent] += count
336			}
337		}
338	
339		// Header line: CONTRIBUTIONS  N checkpoints
340		totalLabel := ""
341		if total > 0 {
342			totalLabel = sty.render(sty.muted, fmt.Sprintf("  %d checkpoints", total))
343		}
344		fmt.Fprintf(w, "%s%s\n", sty.render(sty.label, "CONTRIBUTIONS"), totalLabel)
345	
346		if len(hourly) == 0 {
347			fmt.Fprintln(w, sty.render(sty.muted, "  No activity data"))
348			return
349		}
350	
351		// Determine date range
352		now := time.Now().Local()
353		today := time.Date(now.Year(), now.Month(), now.Day(), 0, 0, 0, 0, now.Location())
354		numDays := 30
355	
356		labelWidth := 3
357		chartCols := sty.width - labelWidth - 2
358		if chartCols < 20 {
359			chartCols = 20
360		}
361	
362		// 6 braille rows × 4 dots = 24 hours
363		chartRows := 6
364		dotsX := chartCols * 2
365		dotsY := chartRows * 4
366	
367		type dotInfo struct {
368			set     bool
369			agentID string
370			value   int
371		}
372		dotGrid := make([][]dotInfo, dotsY)
373		for i := range dotGrid {
374			dotGrid[i] = make([]dotInfo, dotsX)
375		}
376	
377		for _, p := range hourly {
378			pt, err := time.ParseInLocation("2006-01-02", p.Date, time.Local)
379			if err != nil {
380				continue
381			}
382			dayIdx := int(today.Sub(pt).Hours() / 24)
383			dayFromStart := numDays - 1 - dayIdx
384			if dayFromStart < 0 || dayFromStart >= numDays {
385				continue
386			}
387	
388			dx := int(float64(dayFromStart) / float64(numDays) * float64(dotsX))
389			if dx >= dotsX {
390				dx = dotsX - 1
391			}
392	
393			dy := p.Hour
394			if dy >= dotsY {
395				dy = dotsY - 1
396			}
397	
398			// Bubble radius scales with value
399			radius := 0
400			if p.Value >= 3 {
401				radius = 1
402			}
403			if p.Value >= 8 {
404				radius = 2
405			}
406	
407			for oy := -radius; oy <= radius; oy++ {
408				for ox := -radius; ox <= radius; ox++ {
409					if ox*ox+oy*oy > radius*radius+1 {
410						continue
411					}
412					ny, nx := dy+oy, dx+ox
413					if ny >= 0 && ny < dotsY && nx >= 0 && nx < dotsX {
414						if p.Value > dotGrid[ny][nx].value {
415							dotGrid[ny][nx] = dotInfo{set: true, agentID: p.AgentID, value: p.Value}
416						}
417					}
418				}
419			}
420		}
421	
422		// Date axis labels
423		fmt.Fprint(w, strings.Repeat(" ", labelWidth+1))
424		startDate := today.AddDate(0, 0, -(numDays - 1))
425		lastMonth := ""
426		for col := 0; col < chartCols; col++ {
427			dayFrac := float64(col) / float64(chartCols) * float64(numDays)
428			date := startDate.AddDate(0, 0, int(dayFrac))
429			month := date.Format("Jan")
430			if month != lastMonth {
431				fmt.Fprint(w, sty.render(sty.muted, month))
432				col += len(month) - 1
433				lastMonth = month
434			} else {
435				fmt.Fprint(w, " ")
436			}
437		}
438		fmt.Fprintln(w)
439	
440		// Render braille grid
441		hourLabels := []string{" 0", " 4", " 8", "12", "16", "20"}
442	
443		for cy := range chartRows {
444			fmt.Fprint(w, sty.render(sty.dim, hourLabels[cy])+" ")
445	
446			for cx := range chartCols {
447				var brailleCode rune = 0x2800
448				dominantAgent := ""
449				maxVal := 0
450	
451				// Braille dot layout: each char is 2 wide × 4 tall
452				//   dot1 dot4     bit0 bit3
453				//   dot2 dot5     bit1 bit4
454				//   dot3 dot6     bit2 bit5
455				//   dot7 dot8     bit6 bit7
456				dotBits := [8][2]int{
457					{0, 0}, {1, 0}, {2, 0}, {0, 1},
458					{1, 1}, {2, 1}, {3, 0}, {3, 1},
459				}
460	
461				for bit, offset := range dotBits {
462					dy := cy*4 + offset[0]
463					dx := cx*2 + offset[1]
464					if dy < dotsY && dx < dotsX && dotGrid[dy][dx].set {
465						brailleCode |= 1 << bit
466						if dotGrid[dy][dx].value > maxVal {
467							maxVal = dotGrid[dy][dx].value
468							dominantAgent = dotGrid[dy][dx].agentID
469						}
470					}
471				}
472	
473				if brailleCode == 0x2800 {
474					fmt.Fprint(w, " ")
475				} else {
476					fmt.Fprint(w, sty.renderAgent(dominantAgent, string(brailleCode)))
477				}
478			}
479			fmt.Fprintln(w)
480		}
481	
482		// Agent legend
483		if total > 0 {
484			var parts []string
485			for _, id := range agentOrder {
486				count, ok := agentTotals[id]
487				if !ok || count == 0 {
488					continue
489				}
490				pct := float64(count) / float64(total) * 100
491				display := agentDisplayMap[id]
492				parts = append(parts, sty.renderAgent(id, fmt.Sprintf("● %s %d%%", display.Label, int(math.Round(pct)))))
493			}
494			fmt.Fprintln(w, strings.Join(parts, sty.render(sty.dim, "  ")))
495		}
496	}
