546	func renderAgentBar(sty activityStyles, agents map[string]int, maxCount, barWidth int) string {
547		if maxCount == 0 {
548			return strings.Repeat(" ", barWidth)
549		}
550	
551		var b strings.Builder
552	
553		filled := 0
554		for _, id := range agentOrder {
555			count, ok := agents[id]
556			if !ok || count == 0 {
557				continue
558			}
559			segWidth := int(math.Round(float64(count) / float64(maxCount) * float64(barWidth)))
560			if segWidth < 1 && count > 0 {
561				segWidth = 1
562			}
563			if filled+segWidth > barWidth {
564				segWidth = barWidth - filled
565			}
566			if segWidth <= 0 {
567				continue
568			}
569	
570			display := agentDisplayMap[id]
571			seg := strings.Repeat(string(display.Char), segWidth)
572			b.WriteString(sty.renderAgent(id, seg))
573			filled += segWidth
574		}
575	
576		if filled < barWidth {
577			b.WriteString(sty.render(sty.dim, strings.Repeat("░", barWidth-filled)))
578		}
579	
580		return b.String()
581	}
